module binary_counter_tc_5bit(
    input wire clk,
    input wire rst,
    output reg [4:0] count,
    output reg tc
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 5'b00000;
            tc <= 1'b0;
        end else if (count == 5'b11111) begin
            count <= 5'b00000;
            tc <= 1'b1;
        end else begin
            count <= count + 1;
            tc <= 1'b0;
        end
    end
endmodule

