module washing_machine (
	input clk,
	input resetn,
	input start,
	output washing);

	parameter IDLE=0, WASH=1, RINSE=2, SPIN=3;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state != IDLE) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			IDLE: next_state = start ? WASH : IDLE;
			WASH: next_state = (counter == 4'b1111) ? RINSE : WASH;
			RINSE: next_state = (counter == 4'b1111) ? SPIN : RINSE;
			SPIN: next_state = (counter == 4'b1111) ? IDLE : SPIN;
			default: next_state = IDLE;
		endcase
	end

	assign washing = (state != IDLE);
endmodule

