module top_module(
    input clk,
    input reset,
    input load,
    input up_down,
    output reg [2:0] count,
    output reg overflow,
    output reg underflow
);reg [2:0] count_reg1, count_reg2;
reg [2:0] count_next;
wire up_down_sync;

assign up_down_sync = (reset) ? 1'b0 : up_down;

always @(posedge clk) begin
    if (reset) begin
        count_reg1 <= 3'b0;
        count_reg2 <= 3'b0;
    end
    else begin
        count_reg1 <= count_next;
        count_reg2 <= count_reg1;
    end
end

always @(*) begin
    if (load) begin
        count_next = 3'b0;
    end
    else begin
        if (up_down_sync) begin
            if (count_reg1 == 3'b111) begin
                count_next = 3'b000;
                overflow = 1'b1;
            end
            else begin
                count_next = count_reg1 + 1'b1;
                overflow = 1'b0;
            end
            underflow = 1'b0;
        end
        else begin
            if (count_reg1 == 3'b000) begin
                count_next = 3'b111;
                underflow = 1'b1;
            end
            else begin
                count_next = count_reg1 - 1'b1;
                underflow = 1'b0;
            end
            overflow = 1'b0;
        end
    end
end

assign count = count_reg2;

endmodule

