module top_module(
BJ_CLK,         
RESET,          
BUTTON_IN,      
BUTTON_OUT      
);input BJ_CLK;
    input RESET;
    input BUTTON_IN;

    output BUTTON_OUT;

    reg BUTTON_IN_Q, BUTTON_IN_2Q, BUTTON_IN_3Q;
    always @(posedge BJ_CLK or negedge RESET)
    begin
        if(~RESET)
            begin
            BUTTON_IN_Q <= 1'b1;
            BUTTON_IN_2Q <= 1'b1;
            BUTTON_IN_3Q <= 1'b1;
