        else
            begin   
            BUTTON_IN_Q <= BUTTON_IN;
            BUTTON_IN_2Q <= BUTTON_IN_Q;
            BUTTON_IN_3Q <= BUTTON_IN_2Q;
            end
    end

    wire BUTTON_OUT = BUTTON_IN_2Q | BUTTON_IN_3Q;

endmodule

