module top_module(
    input clk,
    output reg [3:0] hours,
    output reg [5:0] minutes
);reg [23:0] count = 0;

    always @(posedge clk) begin
        if (count == 1199999) begin // 1 minute has passed
            count <= 0;
            if (minutes == 59) begin // update hours
                minutes <= 0;
                if (hours == 15) // reset to 00:00
                    hours <= 0;
                else
                    hours <= hours + 1;
            end
            else
                minutes <= minutes + 1;
        end
        else
            count <= count + 1;
    end

endmodule

