module dual_clock_fifo(
	input 				clk_write	,
	input 				clk_read	,
	input 				rst			,
	input				write_en	,
	input				read_en		,
	input		[7:0]	data_in		,

	output reg	[7:0]	data_out	,
	output reg 			fifo_full	,
	output reg 			fifo_empty
);

reg [7:0] fifo_mem [15:0];
reg [3:0] write_pointer;
reg [3:0] read_pointer;
reg [3:0] fifo_count;

always@(posedge clk_write or posedge rst)
begin
	if(rst)
		write_pointer <= 0;
	else if(write_en && !fifo_full)
	begin
		fifo_mem[write_pointer] <= data_in;
		write_pointer <= write_pointer + 1;
	end
end

always@(posedge clk_read or posedge rst)
begin
	if(rst)
		read_pointer <= 0;
	else if(read_en && !fifo_empty)
	begin
		data_out <= fifo_mem[read_pointer];
		read_pointer <= read_pointer + 1;
	end
end

always@(posedge clk_write or posedge clk_read or posedge rst)
begin
	if(rst)
		fifo_count <= 0;
	else if(write_en && !fifo_full && read_en && !fifo_empty)
		fifo_count <= fifo_count;
	else if(write_en && !fifo_full)
		fifo_count <= fifo_count + 1;
	else if(read_en && !fifo_empty)
		fifo_count <= fifo_count - 1;
end

always@(posedge clk_write or posedge clk_read or posedge rst)
begin
	if(rst)
	begin
		fifo_full <= 0;
		fifo_empty <= 1;
	end
	else
	begin
		fifo_full <= (fifo_count == 16);
		fifo_empty <= (fifo_count == 0);
	end
end

endmodule

