module fsm_module (
        input clk,
        input reset,
        input in1,
        input in2,
        input in3,
        output reg out);

    parameter S0 = 0, S1 = 1, S2 = 2;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            S0: next_state = in1 ? S1 : S0;
            S1: next_state = in2 ? S2 : S1;
            S2: next_state = in3 ? S0 : S2;
            default: next_state = 'x;
        endcase
    end

    assign out = (state == S1) || (state == S2);

endmodule

