    RW <= 1'b0;  // Example value, change as needed
    E <= 1'b1;   // Example value, change as needed 
    RS_RW_E_reg <= {RS, RW, E};
    D_reg <= data[k-1:0]; // Take only the lower k bits of data
  end
end

assign RS_RW_E = RS_RW_E_reg;
assign D = D_reg;

endmodule

