module top_module(dout, in0, in1, in2, 
		     sel0_l, sel1_l, sel2_l);parameter SIZE = 1;

output 	[SIZE-1:0] 	dout;
input	[SIZE-1:0]	in0;
input	[SIZE-1:0]	in1;
input	[SIZE-1:0]	in2;
input			sel0_l;
input			sel1_l;
input			sel2_l;




reg	[SIZE-1:0]	dout ;

`ifdef VERPLEX
   $constraint dl_1c_chk3 ($one_cold ({sel2_l,sel1_l,sel0_l}));
`endif

wire [2:0] sel = {sel2_l,sel1_l,sel0_l}; 

always @ (sel0_l or sel1_l or sel2_l or in0 or in1 or in2)

	case ({sel2_l,sel1_l,sel0_l})
		3'b110 : dout = in0 ;
		3'b101 : dout = in1 ;
		3'b011 : dout = in2 ;
	        default : dout = {SIZE{1'bx}} ;
	endcase

endmodule

module top_module( CLK, RST_N, STATSIGS, ADDR, DATA);input CLK; 
 input RST_N; 
 input [7:0] STATSIGS; 
 input [2:0] ADDR; 
 output [31:0] DATA; 
 integer i; 
 reg [31:0] counter [0:7]; 
  always @(posedge CLK or negedge RST_N) 
  for (i=0; i<=7; i=i+1) 
  if (!RST_N) counter[i] <= 32'd0; 
  else counter[i] <= counter[i] + {31'd0,STATSIGS[i]}; 
  assign DATA = counter[ADDR]; 
 endmodule

