  input [15:0] checksum_in,
  output reg error,
  output reg [15:0] checksum_out // Changed from wire to reg
);parameter n = 32; // number of 8-bit data signals

reg [15:0] a = 1;
reg [15:0] b = 0;

integer i;

always @(*) begin
  a = 1; // Reset a and b at the start of the calculation
  b = 0;

  for (i = 0; i < n; i = i + 1) begin
    a = (a + data_in[8*i +: 8]) % 65521;
    b = (b + a) % 65521;
  end

  checksum_out = (b << 8) | a;

  if (checksum_out == checksum_in) begin
    error = 0;
  end else begin
    error = 1;
  end
end

endmodule

