module counter_4bit(CLK, RESET, COUNT);
input CLK, RESET;
output reg [3:0] COUNT;

always @(posedge CLK or posedge RESET) begin
    if (RESET)
        COUNT <= 4'b0000;
    else
        COUNT <= COUNT + 1;
end

endmodule

module down_counter (
	input clk,
	input resetn,
	input load,
	input [3:0] data_in,
	output reg [3:0] count);

always @(posedge clk)
	if (!resetn)
		count <= 4'b0000;
	else if (load)
		count <= data_in;
	else
		count <= count - 1;

endmodule

