module fsm (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter W=0, X=1, Y=2, Z=3;

    always_comb begin
        case (state)
            W: next_state = in ? Y : X;
            X: next_state = in ? Z : W;
            Y: next_state = in ? W : Z;
            Z: next_state = in ? X : Y;
        endcase
    end

    assign out = (state==W) || (state==Y);

endmodule

