    input in,
    input enable,
    output out
);wire out_internal;
assign out = enable ? out_internal : 1'bz;

wire in_not;
assign in_not = ~in;

wire enable_not;
assign enable_not = ~enable;

wire out_internal_1;
assign out_internal_1 = in_not & enable_not;

wire out_internal_2;
assign out_internal_2 = out_internal_1 | out_internal;

assign out_internal = enable ? in : out_internal_2;

endmodule

